
/* ── js/group-setting-api.js ── */

// Group Setting Page - API, Shared State & Constants
// Loaded first: initializes namespace, DOM refs, state, and API/data functions

document.addEventListener('DOMContentLoaded', function() {
    const GSP = window.GroupSettingPage = window.GroupSettingPage || {};

    // ==================== ELEMENTS ====================
    GSP.tablesBody = document.getElementById('tablesBody');
    GSP.addBtn = document.getElementById('addBtn');
    GSP.downloadFieldsBtn = document.getElementById('downloadFieldsBtn');
    GSP.editBtn = document.getElementById('editBtn');
    GSP.viewBtn = document.getElementById('viewBtn');
    GSP.deleteBtn = document.getElementById('deleteBtn');
    GSP.toggleStatusBtn = document.getElementById('toggle-status-btn');
    GSP.addDrawer = document.getElementById('add-drawer');
    GSP.closeDrawerEl = document.getElementById('closeDrawer');
    GSP.cancelDrawer = document.getElementById('cancelDrawer');
    GSP.saveDrawer = document.getElementById('saveDrawer');
    GSP.drawerTitle = document.getElementById('drawerTitle');
    GSP.drawerIcon = document.getElementById('drawerIcon');
    GSP.tableNameInput = document.getElementById('tableName');
    GSP.fieldList = document.getElementById('field-list');
    GSP.fieldCountSpan = document.getElementById('fieldCount');
    GSP.noFieldsMessage = document.getElementById('no-fields-message');
    GSP.addFieldSection = document.querySelector('.add-field-section');
    GSP.newFieldName = document.getElementById('new-field-name');
    GSP.newFieldType = document.getElementById('new-field-type');
    GSP.newFieldMandatory = document.getElementById('new-field-mandatory');
    GSP.addFieldBtnEl = document.getElementById('add-field-btn');
    GSP.modalConfirm = document.getElementById('confirmStatusBtn');
    GSP.statusItemName = document.getElementById('statusItemName');
    GSP.statusNote = document.getElementById('statusNote');
    GSP.confirmDeleteBtn = document.getElementById('confirmDeleteBtn');
    GSP.deleteStaffName = document.getElementById('deleteStaffName');
    GSP.toast = document.getElementById('toast');
    GSP.toastMessage = document.getElementById('toastMessage');
    GSP.searchInput = document.getElementById('searchInput');
    GSP.filterDropdown = document.getElementById('filterDropdown');
    GSP.dropdownToggle = document.getElementById('dropdownToggle');
    GSP.dropdownOptions = document.getElementById('dropdownOptions');
    GSP.selectedText = document.getElementById('selectedText');
    GSP.fieldTypeDropdown = document.getElementById('fieldTypeDropdown');
    GSP.fieldTypeToggle = document.getElementById('fieldTypeToggle');

    // ==================== STATE ====================
    GSP.selectedRow = null;
    GSP.selectedTableId = null;
    GSP.currentMode = 'add';
    GSP.currentFields = [];
    GSP.MAX_FIELDS = 20;
    GSP.groupId = typeof GROUP_ID !== 'undefined' ? GROUP_ID : null;
    GSP.currentFilter = 'all';
    GSP.gsCurrentPage = 1;
    GSP.gsRowsPerPage = 10;

    // ==================== CONSTANTS ====================
    GSP.fieldTypeOptions = [
        { value: 'text', label: 'Text' },
        { value: 'email', label: 'Email' },
        { value: 'class', label: 'Class' },
        { value: 'section', label: 'Section' },
        { value: 'photo', label: 'Photo' },
        { value: 'rel_photo', label: 'Relation Photo' },
        { value: 'barcode', label: 'Barcode' },
        { value: 'qr_code', label: 'QR Code' },
        { value: 'signature', label: 'Signature' }
    ];

    // Image types that have fixed names (not editable)
    GSP.imageFieldTypes = ['photo', 'rel_photo', 'barcode', 'qr_code', 'signature'];

    // Map of image types to their fixed display names
    GSP.imageFieldNames = {
        'photo': 'Photo',
        'rel_photo': 'Relation Photo',
        'barcode': 'Barcode',
        'qr_code': 'QR Code',
        'signature': 'Signature'
    };

    // Image types that should auto-fill and lock field name.
    // rel_photo is intentionally excluded so users can set REL 1 / REL 2 style labels.
    GSP.fixedNameImageFieldTypes = ['photo', 'barcode', 'qr_code', 'signature'];

    // Types with auto-generated names (name input disabled)
    GSP.autoNameTypes = ['class_section', ...GSP.imageFieldTypes];

    // ==================== DATA LOGIC ====================

    // Auto-detect field type from name using fuzzy keyword matching.
    // Uses priority-ordered rules: longer/more-specific patterns matched first.
    // Avoids false positives (e.g. "Designation" will NOT match "Signature")
    // by requiring word-boundary matches for short keywords.
    GSP.detectFieldTypeFromName = function(name) {
        const n = name.toLowerCase().trim().replace(/[_\-]+/g, ' ');
        if (!n) return null;

        // Relation-photo aliases (new canonical type rel_photo)
        if (/^(?:rel(?:ation)?)\s*(?:1|one|2|two)\s*(?:photo|image|pic|picture)$/i.test(n)) {
            return 'rel_photo';
        }
        if (/\b(?:father|mother)\b\s*(?:photo|image|pic|picture)\b/.test(n)) {
            return 'rel_photo';
        }

        // Priority-ordered rules (most specific first)
        // Each rule: [patterns[], fieldType, mode]
        // mode: 'exact' = full string match, 'keyword' = word-boundary match, 'includes' = substring
        const rules = [
            // Relation photo (includes father/mother and explicit relation photo aliases)
            {
                type: 'rel_photo',
                exact: [
                    'relation photo', 'relation image', 'relation pic', 'rel photo',
                    'rel 1 photo', 'rel1photo', 'rel_1photo',
                    'relation 1 photo', 'relation1photo', 'relation one photo',
                    'rel 2 photo', 'rel2photo', 'rel_2photo',
                    'relation 2 photo', 'relation2photo', 'relation two photo',
                    'father photo', "father's photo", 'father image', 'father pic', 'father photograph', 'dad photo', 'papa photo', 'f photo',
                    'mother photo', "mother's photo", 'mother image', 'mother pic', 'mother photograph', 'mom photo', 'maa photo', 'm photo'
                ],
                keywords: ['relation photo', 'relation image', 'relation pic', 'father photo', 'mother photo']
            },
            // Signature  word-boundary to avoid "designation"
            { type: 'signature', exact: ['signature', 'sign', 'student signature', 'child signature', 'student sign'],
              keywords: ['signature'] },
            // QR Code
            { type: 'qr_code', exact: ['qr code', 'qrcode', 'qr', 'qr image'],
              keywords: ['qr code', 'qrcode'] },
            // Barcode
            { type: 'barcode', exact: ['barcode', 'bar code', 'bar image'],
              keywords: ['barcode', 'bar code'] },
                        // Generic photo (after relation-photo patterns)
            { type: 'photo', exact: ['photo', 'photograph', 'student photo', 'student image', 'student pic', 'child photo', 'pic', 'image', 'student photograph', 'passport photo'],
              keywords: ['photo', 'photograph', 'student image', 'student pic'] },
            // Class
            { type: 'class', exact: ['class', 'std', 'standard', 'grade', 'cls'],
              keywords: [] },
            // Section
            { type: 'section', exact: ['section', 'sec', 'division', 'div'],
              keywords: [] },
            // Email
            { type: 'email', exact: ['email', 'e-mail', 'e mail', 'mail', 'email id', 'mail id', 'email address'],
              keywords: ['email', 'e mail'] },
        ];

        // Pass 1: exact match (highest confidence)
        for (const rule of rules) {
            if (rule.exact && rule.exact.indexOf(n) !== -1) return rule.type;
        }

        // Pass 2: word-boundary keyword match (fuzzy but safe)
        for (const rule of rules) {
            for (const kw of (rule.keywords || [])) {
                try {
                    const re = new RegExp('\\b' + kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
                    if (re.test(n)) return rule.type;
                } catch(e) {}
            }
        }

        return null;
    };

    GSP.getFieldTypeLabel = function(value) {
        const option = GSP.fieldTypeOptions.find(o => o.value === value);
        return option ? option.label : value;
    };

    // ==================== API FUNCTIONS ====================

    GSP.downloadTableFields = async function(tableId) {
        try {
            const data = await ApiClient.get(`/api/table/${tableId}/`);

            if (!data.success) {
                showToast(data.message || 'Error fetching table data', 'error');
                return;
            }

            const table = data.table;
            const fields = table.fields || [];

            if (fields.length === 0) {
                showToast('No fields to download!', 'error');
                return;
            }

            // Create Excel workbook using SheetJS
            const headers = fields.map(f => f.name);

            // Create worksheet with headers only
            const wsData = [headers];
            const ws = XLSX.utils.aoa_to_sheet(wsData);

            // Set column widths based on header lengths
            const colWidths = headers.map(h => ({ wch: Math.max(h.length + 5, 15) }));
            ws['!cols'] = colWidths;

            // Create workbook
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, 'Template');

            // Generate filename
            const filename = `${table.name.replace(/[^a-z0-9]/gi, '_')}_template.xlsx`;

            // Download the Excel file
            XLSX.writeFile(wb, filename);

            showToast('Excel template downloaded successfully!', 'success');
        } catch (error) {
            console.error('Download error:', error);
            showToast('Error downloading template', 'error');
        }
    };

    GSP.downloadTableFieldsTxt = async function(tableId) {
        if (!tableId) {
            showToast('Please select a table first.', 'warning');
            return;
        }

        try {
            const data = await ApiClient.get(`/api/table/${tableId}/`);

            if (!data.success) {
                showToast(data.message || 'Error fetching table data', 'error');
                return;
            }

            const table = data.table || {};
            const rawFields = Array.isArray(table.fields) ? table.fields : [];
            const headings = rawFields
                .map(function(field) {
                    if (field && typeof field === 'object') return String(field.name || '').trim();
                    return String(field || '').trim();
                })
                .filter(Boolean);

            if (!headings.length) {
                showToast('No fields available to download.', 'warning');
                return;
            }

            const textContent = headings.join('\r\n');
            const safeTableName = String(table.name || 'table')
                .replace(/[^a-z0-9]/gi, '_')
                .replace(/_+/g, '_')
                .replace(/^_|_$/g, '') || 'table';
            const filename = `${safeTableName}_fields.txt`;

            const blob = new Blob([textContent], { type: 'text/plain;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const anchor = document.createElement('a');
            anchor.href = url;
            anchor.download = filename;
            document.body.appendChild(anchor);
            anchor.click();
            document.body.removeChild(anchor);
            URL.revokeObjectURL(url);

            showToast('Field headings TXT downloaded successfully!', 'success');
        } catch (error) {
            console.error('Download fields TXT error:', error);
            showToast('Error downloading fields TXT', 'error');
        }
    };

    GSP.fetchTableData = async function(tableId) {
        try {
            const data = await ApiClient.get(`/api/table/${tableId}/`);
            if (data.success) return data.table;
            showToast(data.message || 'Error fetching table data', 'error');
            return null;
        } catch (error) {
            showToast('Error fetching table data', 'error');
            return null;
        }
    };

    GSP.saveTable = async function() {
        const name = GSP.tableNameInput.value.trim();
        if (!name) {
            showToast('Please enter a table name!', 'error');
            GSP.tableNameInput.focus();
            return;
        }

        if (GSP.currentFields.length === 0) {
            showToast('Please add at least one field!', 'error');
            return;
        }

        // Prevent double-click
        if (GSP.saveDrawer) {
            GSP.saveDrawer.disabled = true;
            GSP.saveDrawer.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Saving...';
        }

        const payload = {
            name: name,
            fields: GSP.currentFields.map((f, idx) => ({ name: f.name, type: f.type, order: idx, mandatory: f.mandatory || false }))
        };

        try {
            let url = GSP.currentMode === 'add' ? `/api/group/${GSP.groupId}/table/create/` : `/api/table/${GSP.selectedTableId}/update/`;
            const data = await ApiClient.post(url, payload);

            if (data.success) {
                showToast(data.message || 'Table saved successfully!', 'success');
                GSP.closeDrawerModal();
                setTimeout(function() {
                    if (typeof htmx !== 'undefined' && document.getElementById('gs-table-container')) {
                        htmx.trigger(document.body, 'refreshTable');
                    } else {
                        console.warn('group-setting save refresh skipped: HTMX target missing');
                    }
                }, 300);
            } else {
                showToast(data.message || 'Error saving table', 'error');
                // Re-enable button on error
                if (GSP.saveDrawer) {
                    GSP.saveDrawer.disabled = false;
                    GSP.saveDrawer.innerHTML = GSP.currentMode === 'add'
                        ? '<i class="fa-solid fa-plus"></i> Create'
                        : '<i class="fa-solid fa-check"></i> Update';
                }
            }
        } catch (error) {
            showToast('Error saving table', 'error');
            // Re-enable button on error
            if (GSP.saveDrawer) {
                GSP.saveDrawer.disabled = false;
                GSP.saveDrawer.innerHTML = GSP.currentMode === 'add'
                    ? '<i class="fa-solid fa-plus"></i> Create'
                    : '<i class="fa-solid fa-check"></i> Update';
            }
        }
    };

    GSP.toggleStatus = async function() {
        if (!GSP.selectedTableId) return;

        // Prevent double-click
        if (GSP.modalConfirm) GSP.modalConfirm.disabled = true;

        try {
            const data = await ApiClient.post(`/api/table/${GSP.selectedTableId}/toggle-status/`);

            if (data.success) {
                showToast(data.message || 'Status updated!', 'success');
                setTimeout(function() {
                    if (typeof htmx !== 'undefined' && document.getElementById('gs-table-container')) {
                        htmx.trigger(document.body, 'refreshTable');
                    } else {
                        console.warn('group-setting status refresh skipped: HTMX target missing');
                    }
                }, 300);
            } else {
                showToast(data.message || 'Error updating status', 'error');
                if (GSP.modalConfirm) GSP.modalConfirm.disabled = false;
            }
        } catch (error) {
            showToast('Error updating status', 'error');
            if (GSP.modalConfirm) GSP.modalConfirm.disabled = false;
        }
    };
});


/* ── js/group-setting-ui.js ── */

// Group Setting Page - UI Rendering
// Loaded second: drawer, field list, pagination, and visual update functions

document.addEventListener('DOMContentLoaded', function() {
    const GSP = window.GroupSettingPage;

    // ==================== UTILITY FUNCTIONS ====================

    GSP.updateFieldCount = function() {
        if (GSP.fieldCountSpan) GSP.fieldCountSpan.textContent = GSP.currentFields.length;
        if (GSP.noFieldsMessage) GSP.noFieldsMessage.style.display = GSP.currentFields.length === 0 ? 'block' : 'none';
        if (GSP.addFieldBtnEl) GSP.addFieldBtnEl.disabled = GSP.currentFields.length >= GSP.MAX_FIELDS;
    };

    // Reset field type dropdown to default (Text) and enable name input
    GSP.resetFieldTypeDropdown = function() {
        if (GSP.fieldTypeDropdown) {
            GSP.fieldTypeDropdown.querySelectorAll('.dropdown-option').forEach(o => o.classList.remove('selected'));
            const textOption = GSP.fieldTypeDropdown.querySelector('.dropdown-option[data-value="text"]');
            if (textOption) textOption.classList.add('selected');
            if (GSP.fieldTypeToggle) GSP.fieldTypeToggle.querySelector('span').textContent = 'Text';
            if (GSP.newFieldType) GSP.newFieldType.value = 'text';
        }
        // Re-enable name input when resetting to text type
        if (GSP.newFieldName) {
            GSP.newFieldName.disabled = false;
            GSP.newFieldName.classList.remove('disabled');
        }
    };

    // ==================== ACTION BUTTONS ====================

    GSP.updateActionButtons = function() {
        const hasSelection = GSP.selectedRow !== null;
        if (GSP.downloadFieldsBtn) GSP.downloadFieldsBtn.disabled = !hasSelection;
        if (GSP.editBtn) GSP.editBtn.disabled = !hasSelection;
        if (GSP.viewBtn) GSP.viewBtn.disabled = !hasSelection;
        if (GSP.deleteBtn) GSP.deleteBtn.disabled = !hasSelection;
        if (GSP.toggleStatusBtn) GSP.toggleStatusBtn.disabled = !hasSelection;

        // Reprint Cards button
        var isClient = typeof IS_CLIENT_ROLE !== 'undefined' ? IS_CLIENT_ROLE : false;
        var reprintCardsBtn = document.getElementById('reprintCardsBtn');
        if (reprintCardsBtn) {
            reprintCardsBtn.disabled = !hasSelection;
            if (hasSelection && GSP.selectedTableId) {
                var prefix = window.API_BASE_URL || '';
                var rUrl = isClient
                    ? prefix + '/client/table/' + GSP.selectedTableId + '/reprint/'
                    : prefix + '/table/' + GSP.selectedTableId + '/reprint/';
                reprintCardsBtn.onclick = function() { window.location.href = rUrl; };
            }
        }

        // Update toggle status button text and class based on current status
        if (hasSelection && GSP.toggleStatusBtn) {
            const currentStatus = GSP.selectedRow.dataset.tableStatus;
            if (currentStatus === 'active') {
                // Row is Active, so button should show "Inactive" to deactivate
                GSP.toggleStatusBtn.innerHTML = '<i class="fa-solid fa-xmark"></i> Inactive';
                GSP.toggleStatusBtn.classList.remove('btn-active');
                GSP.toggleStatusBtn.classList.add('btn-inactive');
            } else {
                // Row is Inactive, so button should show "Active" to activate
                GSP.toggleStatusBtn.innerHTML = '<i class="fa-solid fa-check"></i> Active';
                GSP.toggleStatusBtn.classList.remove('btn-inactive');
                GSP.toggleStatusBtn.classList.add('btn-active');
            }
        } else if (GSP.toggleStatusBtn) {
            GSP.toggleStatusBtn.innerHTML = '<i class="fa-solid fa-check"></i> Active';
            GSP.toggleStatusBtn.classList.remove('btn-inactive');
            GSP.toggleStatusBtn.classList.add('btn-active');
        }
    };

    // ==================== FIELD LIST RENDERING ====================

    GSP.renderFieldList = function() {
        if (!GSP.fieldList) return;
        GSP.fieldList.innerHTML = '';

        GSP.currentFields.forEach((field, idx) => {
            const li = document.createElement('li');
            li.className = 'field-list-item';
            li.dataset.idx = idx;
            li.draggable = GSP.currentMode !== 'view';

            const typeOptionsHtml = GSP.fieldTypeOptions.map(t =>
                `<option value="${t.value}" ${field.type === t.value ? 'selected' : ''}>${t.label}</option>`
            ).join('');

            const _esc = window.escapeHtml || function(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;'); };
            const requiredIndicatorHtml = field.mandatory
                ? '<span class="mandatory-indicator" title="Required field" aria-hidden="true">*</span>'
                : '';
            // In add/edit mode, field name is an editable input; in view mode it's plain text
            const fieldNameHtml = GSP.currentMode !== 'view'
                ? `<span class="field-name"><span class="field-name-input-wrap"><input type="text" class="field-name-input" data-idx="${idx}" value="${_esc(field.name)}" placeholder="Field name">${requiredIndicatorHtml}</span></span>`
                : `<span class="field-name">${_esc(field.name)}${requiredIndicatorHtml}</span>`;

            // Mandatory checkbox for edit mode
            const mandatoryHtml = GSP.currentMode !== 'view'
                ? `<span class="field-mandatory-cell">
                     <label class="mandatory-toggle" title="Required field">
                       <input type="checkbox" class="field-mandatory-checkbox" data-idx="${idx}" ${field.mandatory ? 'checked' : ''}>
                       <span class="toggle-slider"></span>
                     </label>
                   </span>`
                : '';

            li.innerHTML = `
                <span class="field-drag"><i class="fa-solid fa-grip-vertical"></i></span>
                ${fieldNameHtml}
                <span class="field-type-cell">
                    <select class="field-type-select" data-idx="${idx}" ${GSP.currentMode === 'view' ? 'disabled' : ''}>
                        ${typeOptionsHtml}
                    </select>
                </span>
                ${mandatoryHtml}
                <span class="field-action">
                    ${GSP.currentMode !== 'view' ? `<button class="remove-field-btn" data-idx="${idx}"><i class="fa-solid fa-xmark"></i></button>` : ''}
                </span>
            `;
            GSP.fieldList.appendChild(li);
        });

        GSP.updateFieldCount();
        if (GSP.currentMode !== 'view') GSP.setupDragAndDrop();
    };

    // ==================== DRAG AND DROP ====================

    GSP.setupDragAndDrop = function() {
        const items = GSP.fieldList.querySelectorAll('.field-list-item');
        let draggedItem = null;

        items.forEach(item => {
            item.addEventListener('dragstart', function(e) {
                draggedItem = this;
                this.classList.add('dragging');
                e.dataTransfer.effectAllowed = 'move';
            });

            item.addEventListener('dragend', function() {
                this.classList.remove('dragging');
                draggedItem = null;
                GSP.updateFieldOrder();
            });

            item.addEventListener('dragover', function(e) {
                e.preventDefault();
                e.dataTransfer.dropEffect = 'move';
                const afterElement = GSP.getDragAfterElement(GSP.fieldList, e.clientY);
                if (afterElement == null) {
                    GSP.fieldList.appendChild(draggedItem);
                } else {
                    GSP.fieldList.insertBefore(draggedItem, afterElement);
                }
            });
        });
    };

    GSP.getDragAfterElement = function(container, y) {
        const draggableElements = [...container.querySelectorAll('.field-list-item:not(.dragging)')];
        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - box.height / 2;
            if (offset < 0 && offset > closest.offset) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    };

    GSP.updateFieldOrder = function() {
        const items = GSP.fieldList.querySelectorAll('.field-list-item');
        const newFields = [];
        items.forEach((item, idx) => {
            const oldIdx = parseInt(item.dataset.idx);
            if (GSP.currentFields[oldIdx]) newFields.push({...GSP.currentFields[oldIdx], order: idx});
        });
        GSP.currentFields = newFields;
        GSP.renderFieldList();
    };

    // ==================== DRAWER FUNCTIONS ====================

    GSP.openDrawer = function(mode, data = null) {
        GSP.currentMode = mode;
        GSP.addDrawer.classList.remove('view-mode');

        if (mode === 'add') {
            GSP.drawerTitle.textContent = 'Create New Table';
            GSP.drawerIcon.className = 'fa-solid fa-table-list';
            GSP.tableNameInput.value = '';
            GSP.tableNameInput.disabled = false;
            GSP.currentFields = [];
            GSP.saveDrawer.style.display = 'inline-flex';
            GSP.saveDrawer.innerHTML = '<i class="fa-solid fa-plus"></i> Create';
            GSP.saveDrawer.className = 'btn btn-md btn-primary';
            if (GSP.addFieldSection) GSP.addFieldSection.style.display = 'block';
        } else if (mode === 'edit') {
            GSP.drawerTitle.textContent = 'Edit Table';
            GSP.drawerIcon.className = 'fa-solid fa-pen-to-square';
            GSP.tableNameInput.value = data.name || '';
            GSP.tableNameInput.disabled = false;
            GSP.currentFields = data.fields || [];
            GSP.saveDrawer.style.display = 'inline-flex';
            GSP.saveDrawer.innerHTML = '<i class="fa-solid fa-check"></i> Update';
            GSP.saveDrawer.className = 'btn btn-md btn-primary';
            if (GSP.addFieldSection) GSP.addFieldSection.style.display = 'block';
        } else if (mode === 'view') {
            GSP.drawerTitle.textContent = 'View Table';
            GSP.drawerIcon.className = 'fa-solid fa-eye';
            GSP.tableNameInput.value = data.name || '';
            GSP.tableNameInput.disabled = true;
            GSP.currentFields = data.fields || [];
            GSP.saveDrawer.style.display = 'none';
            if (GSP.addFieldSection) GSP.addFieldSection.style.display = 'none';
            GSP.addDrawer.classList.add('view-mode');
        }

        GSP.renderFieldList();
        GSP.addDrawer.classList.add('open');
        document.body.style.overflow = 'hidden';
    };

    GSP.closeDrawerModal = function() {
        GSP.addDrawer.classList.remove('open');
        GSP.addDrawer.classList.remove('view-mode');
        document.body.style.overflow = '';
        GSP.currentFields = [];
        if (GSP.newFieldName) GSP.newFieldName.value = '';
        GSP.resetFieldTypeDropdown();
    };

    // ==================== FIELD NAME INPUT ====================

    GSP.updateFieldNameInput = function(fieldType) {
        if (!GSP.newFieldName) return;

        if (fieldType === 'class_section') {
            // Class & Section: auto-generate, disable input
            GSP.newFieldName.value = 'Class & Section (auto)';
            GSP.newFieldName.disabled = true;
            GSP.newFieldName.classList.add('disabled');
        } else if ((GSP.fixedNameImageFieldTypes || []).includes(fieldType)) {
            // Image type: auto-fill name and disable input
            GSP.newFieldName.value = GSP.imageFieldNames[fieldType];
            GSP.newFieldName.disabled = true;
            GSP.newFieldName.classList.add('disabled');
        } else {
            // Text/Email: enable input and clear if it was auto-filled
            if (GSP.newFieldName.disabled) {
                GSP.newFieldName.value = '';
            }
            GSP.newFieldName.disabled = false;
            GSP.newFieldName.classList.remove('disabled');
        }
    };

    // ==================== SEARCH, FILTER & PAGINATION ====================

    GSP.getVisibleRows = function() {
        // Returns rows that match the current search/filter (not hidden by search)
        const searchTerm = GSP.searchInput ? GSP.searchInput.value.toLowerCase().trim() : '';
        const allRows = GSP.tablesBody ? Array.from(GSP.tablesBody.querySelectorAll('tr:not(.no-data-row)')) : [];
        if (!searchTerm) return allRows;

        return allRows.filter(row => {
            const name = row.querySelector('td:first-child')?.textContent.toLowerCase() || '';
            const status = row.dataset.tableStatus || '';
            const createdAt = row.querySelector('td:nth-child(3)')?.textContent.toLowerCase() || '';
            const updatedAt = row.querySelector('td:nth-child(4)')?.textContent.toLowerCase() || '';

            if (GSP.currentFilter === 'all') {
                return name.includes(searchTerm) || status.includes(searchTerm) || createdAt.includes(searchTerm) || updatedAt.includes(searchTerm);
            } else if (GSP.currentFilter === 'name') {
                return name.includes(searchTerm);
            } else if (GSP.currentFilter === 'status') {
                return status.includes(searchTerm);
            }
            return true;
        });
    };

    GSP.renderPagination = function() {
        const matched = GSP.getVisibleRows();
        const totalRows = matched.length;
        const totalPages = Math.max(1, Math.ceil(totalRows / GSP.gsRowsPerPage));
        if (GSP.gsCurrentPage > totalPages) GSP.gsCurrentPage = totalPages;

        const startIdx = (GSP.gsCurrentPage - 1) * GSP.gsRowsPerPage;
        const endIdx = Math.min(startIdx + GSP.gsRowsPerPage, totalRows);

        // Hide all rows first, then show only matched rows in the current page range
        const allRows = GSP.tablesBody ? GSP.tablesBody.querySelectorAll('tr:not(.no-data-row)') : [];
        allRows.forEach(r => r.style.display = 'none');
        matched.forEach((row, i) => {
            row.style.display = (i >= startIdx && i < endIdx) ? '' : 'none';
        });

        // Update info text
        const info = document.getElementById('paginationInfo');
        if (info) {
            if (totalRows === 0) {
                info.innerHTML = 'No tables found';
            } else {
                info.innerHTML = `Showing <strong>${startIdx + 1}-${endIdx}</strong> of <strong>${totalRows}</strong> tables`;
            }
        }

        // Page number buttons
        const pageNums = document.getElementById('gsPageNumbers');
        if (pageNums) {
            pageNums.innerHTML = '';
            const maxVisible = 5;
            let startPage = Math.max(1, GSP.gsCurrentPage - Math.floor(maxVisible / 2));
            let endPage = Math.min(totalPages, startPage + maxVisible - 1);
            if (endPage - startPage + 1 < maxVisible) startPage = Math.max(1, endPage - maxVisible + 1);

            for (let p = startPage; p <= endPage; p++) {
                const btn = document.createElement('button');
                btn.className = 'page-num' + (p === GSP.gsCurrentPage ? ' active' : '');
                btn.textContent = p;
                btn.addEventListener('click', () => { GSP.gsCurrentPage = p; GSP.renderPagination(); });
                pageNums.appendChild(btn);
            }
        }

        // Nav buttons
        const firstBtn = document.getElementById('gsFirstPage');
        const prevBtn = document.getElementById('gsPrevPage');
        const nextBtn = document.getElementById('gsNextPage');
        const lastBtn = document.getElementById('gsLastPage');
        if (firstBtn) firstBtn.disabled = GSP.gsCurrentPage <= 1;
        if (prevBtn) prevBtn.disabled = GSP.gsCurrentPage <= 1;
        if (nextBtn) nextBtn.disabled = GSP.gsCurrentPage >= totalPages;
        if (lastBtn) lastBtn.disabled = GSP.gsCurrentPage >= totalPages;
    };

    GSP.performSearch = function() {
        GSP.gsCurrentPage = 1;
        GSP.renderPagination();
    };
});


/* ── js/group-setting-events.js ── */

// Group Setting Page - Event Handlers & Initialization
// Loaded last: binds all event listeners and runs initial setup

document.addEventListener('DOMContentLoaded', function() {
    const GSP = window.GroupSettingPage;

    // ==================== ROW SELECTION ====================
    // Delegate from stable container to survive HTMX swaps
    var gsTableContainer = document.getElementById('gs-table-container') || GSP.tablesBody;
    if (gsTableContainer) {
        gsTableContainer.addEventListener('click', function(e) {
            // Handle download button click
            if (e.target.closest('.download-btn')) {
                e.stopPropagation();
                const btn = e.target.closest('.download-btn');
                const tableId = btn.dataset.tableId;
                GSP.downloadTableFields(tableId);
                return;
            }

            const row = e.target.closest('tr');
            if (!row || !row.dataset.tableId || row.classList.contains('no-data-row')) return;

            if (GSP.selectedRow === row) {
                row.classList.remove('selected');
                GSP.selectedRow = null;
                GSP.selectedTableId = null;
            } else {
                if (GSP.selectedRow) GSP.selectedRow.classList.remove('selected');
                row.classList.add('selected');
                GSP.selectedRow = row;
                GSP.selectedTableId = row.dataset.tableId;
            }
            GSP.updateActionButtons();
        });

        // Double-click on a row  navigate to that table's pending cards
        gsTableContainer.addEventListener('dblclick', function(e) {
            var row = e.target.closest('tr[data-table-id]');
            if (!row || row.classList.contains('no-data-row')) return;
            // Don't navigate when double-clicking action buttons
            if (e.target.closest('.download-btn')) return;
            var tableId = row.dataset.tableId;
            // Use template-set flag (URL-based detection fails for admin on /client/<id>/settings/)
            var isClient = typeof IS_CLIENT_ROLE !== 'undefined' ? IS_CLIENT_ROLE : false;
            var prefix = window.API_BASE_URL || '';
            var basePath = isClient
                ? prefix + '/client/table/' + tableId + '/actions/'
                : prefix + '/table/' + tableId + '/cards/';
            window.location.href = basePath + '?status=pending';
        });
    }

    // ==================== BUTTON HANDLERS ====================

    if (GSP.addBtn) GSP.addBtn.addEventListener('click', () => GSP.openDrawer('add'));

    if (GSP.downloadFieldsBtn) {
        GSP.downloadFieldsBtn.addEventListener('click', () => {
            if (!GSP.selectedTableId) {
                showToast('Please select a table first.', 'warning');
                return;
            }
            GSP.downloadTableFieldsTxt(GSP.selectedTableId);
        });
    }

    if (GSP.editBtn) {
        GSP.editBtn.addEventListener('click', async () => {
            if (GSP.selectedTableId) {
                const tableData = await GSP.fetchTableData(GSP.selectedTableId);
                if (tableData) GSP.openDrawer('edit', tableData);
            }
        });
    }

    if (GSP.viewBtn) {
        GSP.viewBtn.addEventListener('click', async () => {
            if (GSP.selectedTableId) {
                const tableData = await GSP.fetchTableData(GSP.selectedTableId);
                if (tableData) GSP.openDrawer('view', tableData);
            }
        });
    }

    if (GSP.toggleStatusBtn) {
        GSP.toggleStatusBtn.addEventListener('click', () => {
            if (!GSP.selectedRow) return;
            const name = GSP.selectedRow.dataset.tableName;
            const currentStatus = GSP.selectedRow.dataset.tableStatus;
            const newStatus = currentStatus === 'active' ? 'Inactive' : 'Active';

            if (GSP.statusItemName) GSP.statusItemName.textContent = `"${name}"`;
            if (GSP.statusNote) GSP.statusNote.innerHTML = `<i class="fa-solid fa-circle-info"></i> Table will be set to ${newStatus}.`;
            if (window.alpineOpenModal) window.alpineOpenModal('status');
        });
    }

    // Delete button click handler
    if (GSP.deleteBtn) {
        GSP.deleteBtn.addEventListener('click', () => {
            if (!GSP.selectedRow) return;
            const name = GSP.selectedRow.dataset.tableName;
            if (GSP.deleteStaffName) GSP.deleteStaffName.textContent = name;
            if (window.alpineOpenModal) window.alpineOpenModal('delete');
        });
    }

    // ==================== MODAL HANDLERS ====================

    // Delete modal confirm
    // Close handlers now managed by Alpine x-show + @click in template
    if (GSP.confirmDeleteBtn) {
        GSP.confirmDeleteBtn.addEventListener('click', async () => {
            if (window.alpineCloseModal) window.alpineCloseModal();
            if (!GSP.selectedTableId) return;

            // Prevent double-click
            GSP.confirmDeleteBtn.disabled = true;

            try {
                const data = await ApiClient.delete(`/api/table/${GSP.selectedTableId}/delete/`);

                if (data.success) {
                    showToast(data.message || 'Table deleted successfully!', 'success');
                    // Remove the row from DOM
                    if (GSP.selectedRow) GSP.selectedRow.remove();
                    GSP.selectedRow = null;
                    GSP.selectedTableId = null;
                    GSP.updateActionButtons();
                } else {
                    showToast(data.message || 'Error deleting table', 'error');
                }
            } catch (error) {
                console.error('Error deleting table:', error);
                showToast('Error deleting table', 'error');
                GSP.confirmDeleteBtn.disabled = false;
            }
        });
    }

    // Overlay click-to-close + cancel/close buttons now handled by Alpine @click in template
    if (GSP.modalConfirm) GSP.modalConfirm.addEventListener('click', () => {
        if (window.alpineCloseModal) window.alpineCloseModal();
        GSP.toggleStatus();
    });

    // ==================== DRAWER HANDLERS ====================

    if (GSP.closeDrawerEl) GSP.closeDrawerEl.addEventListener('click', GSP.closeDrawerModal);
    if (GSP.cancelDrawer) GSP.cancelDrawer.addEventListener('click', GSP.closeDrawerModal);
    if (GSP.saveDrawer) GSP.saveDrawer.addEventListener('click', GSP.saveTable);
    // Outside click close disabled  prevent accidental closure

    // Escape key closes drawer (modals now handled by Alpine layoutState)
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            if (GSP.addDrawer && GSP.addDrawer.classList.contains('open')) {
                GSP.closeDrawerModal();
            }
            // Alpine handles Escape for activeModal in layoutState()
        }
    });

    // ==================== ADD FIELD HANDLER ====================

    if (GSP.addFieldBtnEl) {
        GSP.addFieldBtnEl.addEventListener('click', () => {
            const type = GSP.newFieldType.value;
            const isMandatory = GSP.newFieldMandatory ? GSP.newFieldMandatory.checked : false;

            // Handle Class & Section: auto-add two fields
            if (type === 'class_section') {
                if (GSP.currentFields.length + 2 > GSP.MAX_FIELDS) {
                    showToast(`Not enough room! Need 2 slots but only ${GSP.MAX_FIELDS - GSP.currentFields.length} left.`, 'warning');
                    return;
                }
                if (GSP.currentFields.some(f => f.name.toLowerCase() === 'class' || f.name.toLowerCase() === 'section')) {
                    showToast('Class or Section field already exists!', 'error');
                    return;
                }
                GSP.currentFields.push({ name: 'CLASS', type: 'class', order: GSP.currentFields.length, mandatory: isMandatory });
                GSP.currentFields.push({ name: 'SECTION', type: 'section', order: GSP.currentFields.length, mandatory: isMandatory });
                GSP.renderFieldList();
                GSP.newFieldName.value = '';
                if (GSP.newFieldMandatory) GSP.newFieldMandatory.checked = false;
                GSP.resetFieldTypeDropdown();
                showToast('Class & Section fields added!', 'success');
                return;
            }

            const name = GSP.newFieldName.value.trim();

            if (!name) { showToast('Please enter a field name!', 'error'); GSP.newFieldName.focus(); return; }
            if (GSP.currentFields.length >= GSP.MAX_FIELDS) { showToast(`Maximum ${GSP.MAX_FIELDS} fields allowed!`, 'warning'); return; }
            if (GSP.currentFields.some(f => f.name.toLowerCase() === name.toLowerCase())) { showToast('Field with this name already exists!', 'error'); return; }

            // Auto-detect field type from name when type is left as default "text"
            let finalType = type;
            if (type === 'text') {
                const detected = GSP.detectFieldTypeFromName(name);
                if (detected) {
                    finalType = detected;
                    const typeLabel = GSP.getFieldTypeLabel(detected);
                    showToast(`Auto-detected "${name}" as ${typeLabel} type`, 'info');
                }
            }

            // Auto-set mandatory for image-type fields
            let finalMandatory = isMandatory;
            if (GSP.imageFieldTypes.includes(finalType)) {
                finalMandatory = true;
            }

            GSP.currentFields.push({ name: name, type: finalType, order: GSP.currentFields.length, mandatory: finalMandatory });
            GSP.renderFieldList();
            GSP.newFieldName.value = '';
            if (GSP.newFieldMandatory) GSP.newFieldMandatory.checked = false;
            GSP.resetFieldTypeDropdown();
            showToast('Field added!', 'success');
        });
    }

    if (GSP.newFieldName) GSP.newFieldName.addEventListener('keypress', (e) => { if (e.key === 'Enter') { e.preventDefault(); GSP.addFieldBtnEl.click(); } });

    // ==================== FIELD TYPE CUSTOM DROPDOWN ====================

    if (GSP.fieldTypeDropdown && GSP.fieldTypeToggle) {
        // Toggle dropdown on button click
        GSP.fieldTypeToggle.addEventListener('click', (e) => {
            e.stopPropagation();
            GSP.fieldTypeDropdown.classList.toggle('open');
        });

        // Handle option selection
        GSP.fieldTypeDropdown.querySelectorAll('.dropdown-option').forEach(option => {
            option.addEventListener('click', function(e) {
                e.stopPropagation();
                // Update selected state
                GSP.fieldTypeDropdown.querySelectorAll('.dropdown-option').forEach(o => o.classList.remove('selected'));
                this.classList.add('selected');

                // Update toggle button text
                GSP.fieldTypeToggle.querySelector('span').textContent = this.textContent;

                // Update hidden input value
                const selectedType = this.dataset.value;
                if (GSP.newFieldType) GSP.newFieldType.value = selectedType;

                // Update name input based on field type
                GSP.updateFieldNameInput(selectedType);

                // Close dropdown
                GSP.fieldTypeDropdown.classList.remove('open');
            });
        });

        // Close dropdown when clicking outside
        document.addEventListener('click', (e) => {
            if (!GSP.fieldTypeDropdown.contains(e.target)) {
                GSP.fieldTypeDropdown.classList.remove('open');
            }
        });
    }

    // ==================== FIELD LIST EVENT HANDLERS ====================

    if (GSP.fieldList) {
        GSP.fieldList.addEventListener('click', (e) => {
            if (e.target.closest('.remove-field-btn')) {
                const idx = parseInt(e.target.closest('.remove-field-btn').dataset.idx);
                GSP.currentFields.splice(idx, 1);
                GSP.renderFieldList();
                showToast('Field removed!', 'info');
            }
        });

        GSP.fieldList.addEventListener('change', (e) => {
            if (e.target.classList.contains('field-type-select')) {
                const idx = parseInt(e.target.dataset.idx);
                GSP.currentFields[idx].type = e.target.value;
                // Auto-set mandatory for image-type fields
                if (GSP.imageFieldTypes.includes(e.target.value)) {
                    GSP.currentFields[idx].mandatory = true;
                    GSP.renderFieldList();
                }
            }
            // Handle mandatory checkbox changes
            if (e.target.classList.contains('field-mandatory-checkbox')) {
                const idx = parseInt(e.target.dataset.idx);
                GSP.currentFields[idx].mandatory = e.target.checked;
            }
        });

        // Sync field name edits back to currentFields
        GSP.fieldList.addEventListener('input', (e) => {
            if (e.target.classList.contains('field-name-input')) {
                const idx = parseInt(e.target.dataset.idx);
                GSP.currentFields[idx].name = e.target.value.trim();
            }
        });
    }

    // ==================== SEARCH & FILTER HANDLERS ====================

    if (GSP.searchInput) GSP.searchInput.addEventListener('input', GSP.performSearch);

    if (GSP.dropdownToggle && GSP.dropdownOptions && GSP.filterDropdown) {
        GSP.dropdownToggle.addEventListener('click', (e) => { e.stopPropagation(); GSP.filterDropdown.classList.toggle('open'); });

        GSP.dropdownOptions.querySelectorAll('.dropdown-option').forEach(option => {
            option.addEventListener('click', function() {
                GSP.dropdownOptions.querySelectorAll('.dropdown-option').forEach(o => o.classList.remove('selected'));
                this.classList.add('selected');
                GSP.selectedText.textContent = this.textContent;
                GSP.currentFilter = this.dataset.value;
                GSP.filterDropdown.classList.remove('open');
                GSP.searchInput.placeholder = `Search by ${this.textContent}...`;
                GSP.performSearch();
            });
        });

        document.addEventListener('click', () => GSP.filterDropdown.classList.remove('open'));
    }

    // ==================== PAGINATION HANDLERS ====================

    document.getElementById('gsFirstPage')?.addEventListener('click', () => { GSP.gsCurrentPage = 1; GSP.renderPagination(); });
    document.getElementById('gsPrevPage')?.addEventListener('click', () => { GSP.gsCurrentPage = Math.max(1, GSP.gsCurrentPage - 1); GSP.renderPagination(); });
    document.getElementById('gsNextPage')?.addEventListener('click', () => { GSP.gsCurrentPage++; GSP.renderPagination(); });
    document.getElementById('gsLastPage')?.addEventListener('click', () => {
        const total = GSP.getVisibleRows().length;
        GSP.gsCurrentPage = Math.max(1, Math.ceil(total / GSP.gsRowsPerPage));
        GSP.renderPagination();
    });

    // Rows-per-page dropdown
    const rowsToggle = document.getElementById('rowsToggle');
    const rowsOptions = document.getElementById('rowsOptions');
    const rowsDropdown = document.getElementById('rowsDropdown');
    const rowsLabel = document.getElementById('rowsLabel');

    if (rowsToggle && rowsOptions) {
        rowsToggle.addEventListener('click', (e) => { e.stopPropagation(); rowsDropdown.classList.toggle('open'); });
        rowsOptions.querySelectorAll('.dropdown-option').forEach(opt => {
            opt.addEventListener('click', function() {
                rowsOptions.querySelectorAll('.dropdown-option').forEach(o => o.classList.remove('selected'));
                this.classList.add('selected');
                if (rowsLabel) rowsLabel.textContent = this.dataset.value;
                GSP.gsRowsPerPage = parseInt(this.dataset.value);
                GSP.gsCurrentPage = 1;
                rowsDropdown.classList.remove('open');
                GSP.renderPagination();
            });
        });
        document.addEventListener('click', (e) => { if (!rowsDropdown.contains(e.target)) rowsDropdown.classList.remove('open'); });
    }

    // ==================== INITIALIZATION ====================
    GSP.updateActionButtons();
    GSP.updateFieldCount();
    GSP.renderPagination();
});
